import{c as a,Q as s,j as t,m as o}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"Managing users","description":"Create, edit, disable, and delete users from the admin panel.","frontmatter":{"title":"Managing users","description":"Create, edit, disable, and delete users from the admin panel."},"headers":[],"relativePath":"src/content/docs/admin/managing-users.md","filePath":"src/content/docs/admin/managing-users.md"}'),r={name:"src/content/docs/admin/managing-users.md"};function n(i,e,l,c,d,u){return s(),t("div",null,[...e[0]||(e[0]=[o('<h2 id="creating-a-user" tabindex="-1">Creating a user <a class="header-anchor" href="#creating-a-user" aria-label="Permalink to &quot;Creating a user&quot;">​</a></h2><p>Go to <code>/admin/users</code> and click <strong>New user</strong>. Enter an email address and choose a sign-in method:</p><ul><li><strong>Email + Password</strong> - the user gets a temporary password (minimum 12 characters) and is required to change it on first login.</li><li><strong>Email Only</strong> - creates a passwordless account. The user signs in with just their email address and a one-time code sent to it. No password is set.</li></ul><p>If allowed email domains are configured in <code>/admin/settings</code>, the email must match one of those domains.</p><h2 id="user-list" tabindex="-1">User list <a class="header-anchor" href="#user-list" aria-label="Permalink to &quot;User list&quot;">​</a></h2><p>The user list shows each user&#39;s avatar, display name (or email if none is set), 2FA status (TOTP enrolled / email only / none), session count, status (active / locked / disabled), and a copy button for the user ID.</p><p>Use the filter chips to narrow to <strong>Active</strong>, <strong>Locked</strong>, <strong>Disabled</strong>, or <strong>No 2FA</strong> users. Type in the search box to filter by email or user ID.</p><h2 id="user-detail-page" tabindex="-1">User detail page <a class="header-anchor" href="#user-detail-page" aria-label="Permalink to &quot;User detail page&quot;">​</a></h2><p>Click any user&#39;s row or the arrow icon to go to their detail page. From here you can:</p><h3 id="account-actions" tabindex="-1">Account actions <a class="header-anchor" href="#account-actions" aria-label="Permalink to &quot;Account actions&quot;">​</a></h3><ul><li><strong>Set password</strong> - directly set a new password. All sessions are revoked.</li><li><strong>Send reset email</strong> - sends a self-service password reset link. Expires in 30 minutes.</li><li><strong>Revoke all sessions</strong> - immediately signs the user out on every device.</li><li><strong>Toggle passwordless</strong> - enable or disable email-only sign-in for this user.</li><li><strong>Reset TOTP</strong> - removes the authenticator enrollment and all recovery codes. The user re-enrolls on next login.</li></ul><h3 id="danger-zone" tabindex="-1">Danger zone <a class="header-anchor" href="#danger-zone" aria-label="Permalink to &quot;Danger zone&quot;">​</a></h3><ul><li><strong>Disable account</strong> - the account cannot log in. Sessions are revoked. Reversible.</li><li><strong>Enable account</strong> - restores a disabled account. No data is lost.</li><li><strong>Delete user</strong> - permanently removes the account, sessions, OIDC grants, and credentials. Requires typing the email to confirm.</li></ul><h2 id="locked-accounts" tabindex="-1">Locked accounts <a class="header-anchor" href="#locked-accounts" aria-label="Permalink to &quot;Locked accounts&quot;">​</a></h2><p>If a user fails OTP verification 5 times in 10 minutes, their account is temporarily locked. The detail page shows a warning banner with an <strong>Unlock now</strong> button if you need to restore access before the automatic lockout expires.</p><h2 id="totp-recovery-codes" tabindex="-1">TOTP recovery codes <a class="header-anchor" href="#totp-recovery-codes" aria-label="Permalink to &quot;TOTP recovery codes&quot;">​</a></h2><p>The detail page shows how many recovery codes remain. GateKeeper stores only argon2id hashes - the actual codes are not recoverable from the database.</p><h2 id="passkeys" tabindex="-1">Passkeys <a class="header-anchor" href="#passkeys" aria-label="Permalink to &quot;Passkeys&quot;">​</a></h2><p>Registered passkeys are listed on the detail page with name and registration date.</p><h2 id="admin-account" tabindex="-1">Admin account <a class="header-anchor" href="#admin-account" aria-label="Permalink to &quot;Admin account&quot;">​</a></h2><p>Your own admin account (password, TOTP, passkeys) is managed at <code>/admin/profile</code> (&quot;My account&quot; in the sidebar).</p>',21)])])}const m=a(r,[["render",n]]);export{g as __pageData,m as default};
